// Calcula cumplimiento y detecta itens reprobados
const b = $input.first().json.body;
const items = b.items || []; // [{nombre, ok:true/false}]
const total = items.length || 1;
const fallas = items.filter(i => !i.ok).map(i => i.nombre);
const cumplimiento = Math.round(((total - fallas.length) / total) * 100);
return [{ json: {
  planta: b.planta, area: b.area, equipo: b.equipo,
  operador: b.operador, turno: b.turno,
  fecha: new Date().toISOString(),
  cumplimiento, fallas: fallas.join('; '),
  critico: fallas.length > 0
}}];

